"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[304],{69544:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"messaging","desc":"","lua_type":"any"},{"name":"onEnvelope","desc":"Called with `(envelope, source)` for each newly seen match.","lua_type":"(any, string) -> ()"},{"name":"fetch","desc":"Reads an envelope from the ledger by matchId, for non-inline messages.","lua_type":"(string) -> any"}],"returns":[],"function_type":"static","source":{"line":67,"path":"src/internal/Broadcaster.luau"}},{"name":"topicFor","desc":"The topic a given server listens on.","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"serverId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"static","source":{"line":88,"path":"src/internal/Broadcaster.luau"}},{"name":"accept","desc":"Records a matchId and reports whether it had not been seen before.\\n\\nBounded to `Defaults.SEEN_CAPACITY` (256) entries, evicted oldest first, so a\\nlong-lived server does not accumulate them.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":105,"path":"src/internal/Broadcaster.luau"}},{"name":"isHealthy","desc":"","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":123,"path":"src/internal/Broadcaster.luau"}},{"name":"markUnhealthy","desc":"Marks delivery unreliable for `BROADCAST_UNHEALTHY_DURATION` seconds.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":135,"path":"src/internal/Broadcaster.luau"}},{"name":"start","desc":"Subscribes to this server\'s topic. Calling it twice does nothing.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":144,"path":"src/internal/Broadcaster.luau"}},{"name":"stop","desc":"","params":[{"name":"self","desc":"","lua_type":"Broadcaster"}],"returns":[],"function_type":"static","source":{"line":156,"path":"src/internal/Broadcaster.luau"}},{"name":"announce","desc":"Publishes a committed match to every other server holding one of its members.\\nCalled only after the match has reached `Ready`.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"envelope","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":193,"path":"src/internal/Broadcaster.luau"}},{"name":"pollInterval","desc":"How long a ticket waits before its next poll, given how many it has already\\nmade.\\n\\nDoubles from `pollInterval` (2 s), capped at `pollIntervalMax` (30 s) while\\ndelivery is healthy and at `pollIntervalUnhealthy` (5 s) while it is not.","params":[{"name":"self","desc":"","lua_type":"Broadcaster"},{"name":"attempt","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":238,"path":"src/internal/Broadcaster.luau"}}],"properties":[],"types":[],"name":"Broadcaster","desc":"Cross-server delivery of committed matches.\\n\\nMemoryStore is the source of truth; MessagingService only shortens the wait.\\nA match is written and flipped to `Ready` before anything is published, so\\nlosing every message costs latency and nothing else.\\n\\n### Addressing\\n\\nOne topic per server, named `<namespace><version>:<serverId>`, with each\\ninstance subscribed to exactly one. A match is published only to the distinct\\nservers holding its members, typically two to six.\\n\\nA single shared topic would instead deliver every match to every server. With\\nRoblox\'s per-universe receive budget of `400 + 200 x servers` per minute,\\nthat caps the experience at roughly 200 matches per minute regardless of\\nsize, so per-server topics are used instead.\\n\\n`topicShards` folds servers into a fixed number of topics if topic\\ncardinality ever needs limiting; `0`, the default, means one per server.\\n\\n### Payload\\n\\nEnvelopes under `inlineBroadcastBytes` (600) are sent inside the message,\\nsaving the receiver a read. Larger ones send only the matchId and the\\nreceiver reads the ledger. An inline envelope is safe to trust because it\\nexists only after the commit succeeded.\\n\\n### Health\\n\\nA failed publish, or a match found by polling that should have arrived as a\\nmessage, marks delivery unhealthy for `BROADCAST_UNHEALTHY_DURATION` (300 s).\\nWhile unhealthy, tickets poll on a much tighter cap.","source":{"line":39,"path":"src/internal/Broadcaster.luau"}}')}}]);